  ]$questions$::jsonb;
begin
  create temporary table fos_bank_targets on commit drop as
  select x.*, c.id as course_id, m.id as module_id, l.id as lesson_id
  from jsonb_to_recordset(v_items) x(
    course text, module text, lesson text, key text, prompt text, options text[], aliases text[], explanation text
  )
  join public.courses c on c.code = x.course
  join public.modules m on m.course_id = c.id and m.title = x.module
  join public.lessons l on l.module_id = m.id and l.course_id = c.id
  join public.lesson_versions lv on lv.lesson_id = l.id and lv.title = x.lesson and lv.status = 'published';

  -- Content can only be installed once its published lessons exist.
  if not exists (select 1 from fos_bank_targets) then return; end if;
  if exists (select 1 from fos_bank_targets group by course_id, key having count(*) > 1) then
    raise exception 'Faculty of Science bank has an ambiguous course lesson mapping.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(v_items) x(course text, key text)
    where exists (select 1 from fos_bank_targets t where t.course = x.course)
      and not exists (select 1 from fos_bank_targets t where t.course = x.course and t.key = x.key)
  ) then raise exception 'A published lesson is missing for the Faculty of Science bank.'; end if;

  select r.user_id into v_admin from public.user_roles r
  join public.profiles p on p.id = r.user_id and p.deactivated_at is null
  where r.role = 'admin' order by r.user_id limit 1;
  if v_admin is null then raise exception 'Publishing the Faculty of Science bank requires an active administrator.'; end if;

  -- Never turn a question already used in protected content into personal practice.
  delete from fos_bank_targets x
  where private.study_question_is_protected(x.course_id, null, x.prompt);

  insert into public.questions(course_id, lesson_id, pool, logical_key)
  select course_id, lesson_id, 'learning', key from fos_bank_targets;

  insert into public.question_versions(question_id, version, prompt, difficulty, usage, source_reference, answer_format)
  select q.id, 1, x.prompt, 'intermediate', array['practice'],
    'Published ' || x.course || ' lesson: ' || x.lesson,
    case when x.options is null then 'fill_in_gap' else 'standard' end
  from fos_bank_targets x join public.questions q on q.course_id = x.course_id and q.logical_key = x.key;

  insert into public.question_options(question_version_id, label, body, position)
  select v.id, chr(64 + opt.position::integer), opt.body, opt.position::integer
  from fos_bank_targets x join public.questions q on q.course_id = x.course_id and q.logical_key = x.key
  join public.question_versions v on v.question_id = q.id and v.version = 1
  cross join lateral unnest(x.options) with ordinality opt(body, position);

  insert into private.question_answer_keys(question_version_id, correct_option_id, explanation, gap_answers)
  select v.id, o.id, x.explanation,
    case when x.aliases is not null then jsonb_build_array(jsonb_build_object('index', 0, 'accepted_answers', x.aliases)) end
  from fos_bank_targets x join public.questions q on q.course_id = x.course_id and q.logical_key = x.key
  join public.question_versions v on v.question_id = q.id and v.version = 1
  left join public.question_options o on o.question_version_id = v.id and o.position = 1;

  for v_question in
    select v.id from fos_bank_targets x join public.questions q on q.course_id = x.course_id and q.logical_key = x.key
    join public.question_versions v on v.question_id = q.id and v.version = 1
  loop
    perform private.publish_question_version(v_question.id, v_admin);
  end loop;

  -- Use the published module as a study unit and preserve every original lesson ID.
  insert into private.topic_quiz_unit_members(lesson_id, unit_id, title)
  select l.id, first_value(l.id) over (partition by m.id order by l.position, l.id), m.title
  from public.modules m join public.lessons l on l.module_id = m.id
  join public.lesson_versions lv on lv.lesson_id = l.id and lv.status = 'published'
  where exists (select 1 from fos_bank_targets x where x.module_id = m.id)
  on conflict (lesson_id) do nothing;

  if exists (
    select 1
    from (select distinct course_id, module_id from fos_bank_targets) target
    cross join lateral (select count(*) as questions from private.topic_quiz_pool_v2(null, target.course_id) pool
      join public.lessons l on l.id = pool.lesson_id and l.module_id = target.module_id) totals
    where totals.questions < 20
  ) then raise exception 'A Faculty of Science practice unit has fewer than 20 eligible questions.'; end if;
end;
$bank$;

commit;
